const daysSince = s => Math.floor((Date.now() - new Date(s).getTime())/86400000);
const ago = s => new Date(Date.now() - s*1000).toISOString();
return [
 {id:'INQ-001', received_at:ago(20), name:'Dana Whitfield', email:'dana@example.com', message:'I was rear-ended last week and the insurer is refusing to pay. Can you help?'},
 {id:'INQ-002', received_at:ago(35), name:'Marcus Lee', email:'marcus@example.com', message:'We need a commercial lease reviewed before Friday.'},
 {id:'INQ-003', received_at:ago(12), name:'Priya Nair', email:'priya@example.com', message:'My landlord is trying to evict me and the hearing is tomorrow morning.'},
 {id:'INQ-004', received_at:ago(50), name:'SEO Partners', email:'sales@example.org', message:'We offer link building packages for law firms.'}
].map(json => ({json}));

const AREAS = [
 ['personal_injury', /accident|rear-ended|injur|insurer/i],
 ['commercial', /lease|contract|company|commercial/i],
 ['housing', /landlord|evict|tenant|rent/i],
 ['not_a_client', /we offer|packages|link building|partnership/i]
];
return $input.all().map(({json}) => {
 const hit = AREAS.find(([, re]) => re.test(json.message));
 const area = hit ? hit[0] : 'general';
 const urgent = /tomorrow|today|urgent|hearing|deadline|friday/i.test(json.message);
 const response_time_seconds = Math.round((Date.now() - new Date(json.received_at).getTime())/1000);
 return {json: {...json, area, urgent, response_time_seconds, needs_action: area !== 'not_a_client', reason: area === 'not_a_client' ? 'sales pitch, not a client' : 'new client inquiry'}};
});

const TEAM = {personal_injury:'personal injury', commercial:'commercial', housing:'housing', general:'intake'};
return $input.all().map(({json}) => {
 const first = json.name.split(' ')[0];
 const next = json.urgent ? 'Because your matter is time-sensitive, a lawyer will call you today.' : 'A lawyer will reply within one business day.';
 const message = `Hi ${first}, thank you for contacting Harlow & Reed. Your message has reached our ${TEAM[json.area]} team. ${next} To prepare, please reply with any documents or dates you already have. This message was prepared by an automated assistant. It is not legal advice.`;
 return {json: {...json, channel:'email', to: json.email, subject:'We received your inquiry', message, approval: json.urgent ? 'notify_owner_now' : 'auto_send_ack'}};
});
